const mount = $('Mount: host-a').first().json;
const startSync = $('Start sync: host-a').first().json;
const rclone = $('Wait for sync: host-a').first().json;
const umount = $('Unmount: host-a').first().json;
const sizeCheck = $('Check Size: host-a').first().json;

function ok(item) {
  if (item === undefined || item === null) return false;
  if (item.code !== undefined) return item.code === 0;
  if (item.exitCode !== undefined) return item.exitCode === 0;
  return !item.error;
}

function formatBytes(bytes) {
  if (bytes === undefined || bytes === null || isNaN(bytes)) return 'unknown';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0, n = bytes;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  return n.toFixed(2) + ' ' + units[i];
}

function extractUploadedBytes(stdout) {
  if (!stdout) return undefined;
  const lines = stdout.split('\n').filter(l => l.trim().length > 0);
  let lastBytes = undefined;
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line);
      if (parsed && parsed.stats && typeof parsed.stats.bytes === 'number') {
        lastBytes = parsed.stats.bytes;
      }
    } catch (e) { /* skip non-JSON lines */ }
  }
  return lastBytes;
}

let status = 'success';
let error = '';

if (!ok(mount)) {
  status = 'failed';
  error = 'Mount failed: ' + (mount.stderr || mount.error || JSON.stringify(mount));
} else if (!ok(rclone)) {
  status = 'failed';
  error = 'rclone sync failed: ' + (rclone.stderr || rclone.error || JSON.stringify(rclone));
}
const umountWarning = !ok(umount) ? ('Warning - umount failed: ' + (umount.stderr || umount.error || '')) : '';

let uploadedHuman = 'unknown';
try { uploadedHuman = formatBytes(extractUploadedBytes(rclone.stdout)); } catch (e) {}

let sizeHuman = 'unknown';
try { sizeHuman = formatBytes(JSON.parse(sizeCheck.stdout).bytes); } catch (e) {}

return [{ json: { host: 'host-a', status, error, umountWarning, uploadedHuman, sizeHuman } }];

